question.answer:
package main

func crossings(passengers, capacity int) int {
	trips := 0
	for passengers > 0 {
		passengers -= capacity
		trips++
	}
	return trips
}

func departures(first, last, every int) int {
	count := 0
	for hour := first; hour <= last; hour += every {
		count++
	}
	return count
}

func portSide(n int) int {
	count := 0
	for ticket := range n {
		if ticket%2 == 0 {
			count++
		}
	}
	return count
}

