question.answer:
package main

func force(knots int) int {
	switch {
	case knots < 1:
		return 0
	case knots < 11:
		return 3
	case knots < 28:
		return 6
	case knots < 48:
		return 9
	default:
		return 12
	}
}

func describe(level int) string {
	switch level {
	case 0:
		return "calm"
	case 3, 6:
		return "breeze"
	case 9:
		return "gale"
	case 12:
		return "storm"
	default:
		return "unknown"
	}
}

func canSail(knots, licence int) bool {
	if f := force(knots); f <= licence {
		return true
	}
	return false
}

