question.answer:
package main

func firstPair(tables, seats, wish int) (int, int) {
	table, seat := 0, 0
Tables:
	for t := 1; t <= tables; t++ {
		for s := 1; s <= seats; s++ {
			switch {
			case t*s == wish:
				table, seat = t, s
				break Tables
			case t*s > wish:
				continue Tables
			}
		}
	}
	return table, seat
}

func consolations(tables, seats, wish int) int {
	prizes := 0
Tables:
	for t := 1; t <= tables; t++ {
		for s := 1; s <= seats; s++ {
			if t*s == wish {
				continue Tables
			}
		}
		prizes++
	}
	return prizes
}

func rounds(couples, floor int) int {
	played := 0
	for {
		couples *= 2
		if couples > floor {
			break
		}
		played++
	}
	return played
}
